1	use std::collections::BTreeMap;
2	use std::path::{Path, PathBuf};
3	use std::sync::Mutex;
4	
5	use callisto_model::{Ecosystem, ManifestRole, PackageId};
6	
7	use crate::error::GraphError;
8	
9	/// Test-observability counter: total number of times [`IdentityResolver::resolve`]
10	/// has actually read and parsed a manifest from disk (i.e. missed its memo).
11	/// Production code never reads this; it exists so callers can write
12	/// regression tests asserting that a given `(path, ecosystem)` pair is
13	/// resolved (read + parsed) at most once per [`IdentityResolver`] lifetime,
14	/// instead of once per caller. Mirrors `callisto_manifests::open_call_count`.
15	static IDENTITY_READ_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
16	
17	/// Resets the internal identity-read call counter to zero. Intended for use in test setup.
18	pub fn reset_identity_read_count() {
19	    IDENTITY_READ_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
20	}
21	
22	/// Reads the current value of the internal identity-read call counter.
23	pub fn identity_read_count() -> usize {
24	    IDENTITY_READ_COUNT.load(std::sync::atomic::Ordering::SeqCst)
25	}
26	
27	pub struct IdentityResolver {
28	    workspace_root: PathBuf,
29	    /// Memoizes `resolve`'s result per `(project_root, ecosystem)` so a
30	    /// manifest referenced by many dependency edges (e.g. a widely-depended-on
31	    /// shared crate) is read and parsed from disk at most once per resolver
32	    /// lifetime, rather than once per caller. `MoonProjectLocator` holds a
33	    /// single `IdentityResolver` for its whole lifetime, so this memo spans
34	    /// both `projects()` and `declared_edges()` -- the two call sites that
35	    /// previously re-resolved the same identity independently.
36	    memo: Mutex<BTreeMap<(PathBuf, Ecosystem), PackageId>>,
37	}
38	
39	impl IdentityResolver {
40	    pub fn new(workspace_root: &Path) -> Result<Self, GraphError> {
41	        Ok(IdentityResolver {
42	            workspace_root: workspace_root.to_path_buf(),
43	            memo: Mutex::new(BTreeMap::new()),
44	        })
45	    }
46	
47	    pub fn resolve(&self, project_root: &Path, ecosystem: Ecosystem) -> Result<PackageId, GraphError> {
48	        let key = (project_root.to_path_buf(), ecosystem);
49	        if let Some(id) = self.memo.lock().unwrap_or_else(|e| e.into_inner()).get(&key) {
50	            return Ok(id.clone());
51	        }
52	
53	        let abs = self.workspace_root.join(project_root);
54	        let Some(format) = ecosystem.canonical_manifest_format() else {
55	            return Err(GraphError::AmbiguousName {
56	                name: "unsupported ecosystem".to_string(),
57	                candidates: Vec::new(),
58	            });
59	        };
60	
61	        let manifest_rel = project_root.join(format.file_name());
62	        let manifest_abs = abs.join(format.file_name());
63	        IDENTITY_READ_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
64	        let content = std::fs::read_to_string(&manifest_abs).map_err(|e| callisto_model::ManifestError::Read {
65	            path: manifest_rel.clone(),
66	            message: e.to_string(),
67	        })?;
68	        let identity = callisto_manifests::read_identity(format, &content, &manifest_rel)?;
69	        let name = identity.name.ok_or(callisto_model::ManifestError::MissingField {
70	            path: manifest_rel,
71	            field: match ecosystem {
72	                Ecosystem::Cargo => "package.name",
73	                Ecosystem::Npm => "name",
74	                _ => "project.name / tool.poetry.name / tool.flit.metadata.module",
75	            },
76	        })?;
77	
78	        let id = PackageId::parse(&name).map_err(|_err| GraphError::AmbiguousName {
79	            name: name.clone(),
80	            candidates: Vec::new(),
81	        })?;
82	
83	        self.memo
84	            .lock()
85	            .unwrap_or_else(|e| e.into_inner())
86	            .insert(key, id.clone());
87	        Ok(id)
88	    }
89	}
90	
91	#[cfg(test)]
92	mod tests {
93	    use super::*;
94	
95	    #[test]
96	    fn resolves_cargo_package_name() {
97	        let dir = tempfile::tempdir().unwrap();
98	        std::fs::write(
99	            dir.path().join("Cargo.toml"),
100	            "[package]\nname = \"my-crate\"\nversion = \"0.1.0\"\n",
101	        )
102	        .unwrap();
103	        let resolver = IdentityResolver::new(dir.path()).unwrap();
104	        let id = resolver.resolve(std::path::Path::new("."), Ecosystem::Cargo).unwrap();
105	        assert_eq!(id.name(), "my-crate");
106	    }
107	
108	    /// A `Cargo.toml` using `version.workspace = true` (real-world common
109	    /// case) must still resolve by name alone -- a package's *name* is
110	    /// never workspace-inherited in Cargo, so this must succeed without
111	    /// any `WorkspaceInheritance` context, which `IdentityResolver` (used
112	    /// from `callisto-moon`'s WASM PDK entry points, which have no such
113	    /// context available) deliberately never builds.
114	    #[test]
115	    fn resolves_cargo_package_name_with_workspace_inherited_version() {
116	        let dir = tempfile::tempdir().unwrap();
117	        std::fs::write(
118	            dir.path().join("Cargo.toml"),
119	            "[package]\nname = \"inheriting-crate\"\nversion.workspace = true\nedition.workspace = true\n",
120	        )
121	        .unwrap();
122	        let resolver = IdentityResolver::new(dir.path()).unwrap();
123	        let id = resolver.resolve(std::path::Path::new("."), Ecosystem::Cargo).unwrap();
124	        assert_eq!(id.name(), "inheriting-crate");
125	    }
126	
127	    #[test]
128	    fn resolves_npm_package_name() {
129	        let dir = tempfile::tempdir().unwrap();
130	        std::fs::write(
131	            dir.path().join("package.json"),
132	            r#"{"name":"my-pkg","version":"1.0.0"}"#,
133	        )
134	        .unwrap();
135	        let resolver = IdentityResolver::new(dir.path()).unwrap();
136	        let id = resolver.resolve(std::path::Path::new("."), Ecosystem::Npm).unwrap();
137	        assert_eq!(id.name(), "my-pkg");
138	    }
139	
140	    #[test]
141	    fn resolves_pypi_package_name_pep621() {
142	        let dir = tempfile::tempdir().unwrap();
143	        std::fs::write(
144	            dir.path().join("pyproject.toml"),
145	            "[project]\nname = \"my-lib\"\nversion = \"1.0.0\"\n",
146	        )
147	        .unwrap();
148	        let resolver = IdentityResolver::new(dir.path()).unwrap();
149	        let id = resolver.resolve(std::path::Path::new("."), Ecosystem::Pypi).unwrap();
150	        assert_eq!(id.name(), "my-lib");
151	    }
152	
153	    #[test]
154	    fn resolves_pypi_package_name_poetry_fallback() {
155	        let dir = tempfile::tempdir().unwrap();
156	        std::fs::write(
157	            dir.path().join("pyproject.toml"),
158	            "[tool.poetry]\nname = \"my-poetry-lib\"\nversion = \"1.0.0\"\n",
159	        )
160	        .unwrap();
161	        let resolver = IdentityResolver::new(dir.path()).unwrap();
162	        let id = resolver.resolve(std::path::Path::new("."), Ecosystem::Pypi).unwrap();
163	        assert_eq!(id.name(), "my-poetry-lib");
164	    }
165	
166	    /// Before the shared-extractor refactor, IdentityResolver's Pypi branch
167	    /// only checked PEP 621 then Poetry -- unlike
168	    /// `PyprojectToml::package_name()`, which also falls back to Flit's
169	    /// `[tool.flit.metadata].module`. A Flit-based Python package could be
170	    /// resolved via the Manifest trait but not via IdentityResolver. The
171	    /// shared `python_package_name` extractor closes this gap as a
172	    /// side effect of removing the duplication.
173	    #[test]
174	    fn resolves_pypi_package_name_flit_fallback() {
175	        let dir = tempfile::tempdir().unwrap();
176	        std::fs::write(
177	            dir.path().join("pyproject.toml"),
178	            "[tool.flit.metadata]\nmodule = \"my_flit_lib\"\n",
179	        )
180	        .unwrap();
181	        let resolver = IdentityResolver::new(dir.path()).unwrap();
182	        let id = resolver.resolve(std::path::Path::new("."), Ecosystem::Pypi).unwrap();
183	        assert_eq!(id.name(), "my_flit_lib");
184	    }
185	
186	    #[test]
187	    fn resolve_errors_when_manifest_file_missing() {
188	        let dir = tempfile::tempdir().unwrap();
189	        let resolver = IdentityResolver::new(dir.path()).unwrap();
190	        let result = resolver.resolve(std::path::Path::new("."), Ecosystem::Cargo);
191	        assert!(result.is_err());
192	    }
193	
194	    /// F16 regression: a second `resolve` call for the identical
195	    /// `(project_root, ecosystem)` pair must be served from the memo, not
196	    /// re-read from disk. Proven by deleting the manifest file between the
197	    /// two calls -- if the second call fell through to disk, it would error
198	    /// (file missing) instead of returning the memoized id.
199	    #[test]
200	    fn resolve_memoizes_and_does_not_re_read_deleted_manifest() {
201	        let dir = tempfile::tempdir().unwrap();
202	        let manifest_path = dir.path().join("Cargo.toml");
203	        std::fs::write(
204	            &manifest_path,
205	            "[package]\nname = \"memo-crate\"\nversion = \"0.1.0\"\n",
206	        )
207	        .unwrap();
208	        let resolver = IdentityResolver::new(dir.path()).unwrap();
209	
210	        let first = resolver.resolve(std::path::Path::new("."), Ecosystem::Cargo).unwrap();
211	        assert_eq!(first.name(), "memo-crate");
212	
213	        std::fs::remove_file(&manifest_path).unwrap();
214	
215	        let second = resolver
216	            .resolve(std::path::Path::new("."), Ecosystem::Cargo)
217	            .expect("second resolve must be served from the memo, not re-read the (now-deleted) manifest");
218	        assert_eq!(second, first);
219	    }
220	
221	    /// F16 regression: distinct `(path, ecosystem)` keys must not collide in
222	    /// the memo -- resolving one path/ecosystem pair must not poison the
223	    /// cache entry for a different pair.
224	    #[test]
225	    fn resolve_memo_is_keyed_by_both_path_and_ecosystem() {
226	        let dir = tempfile::tempdir().unwrap();
227	        std::fs::create_dir_all(dir.path().join("a")).unwrap();
228	        std::fs::create_dir_all(dir.path().join("b")).unwrap();
229	        std::fs::write(
230	            dir.path().join("a/Cargo.toml"),
231	            "[package]\nname = \"crate-a\"\nversion = \"0.1.0\"\n",
232	        )
233	        .unwrap();
234	        std::fs::write(
235	            dir.path().join("b/package.json"),
236	            r#"{"name":"pkg-b","version":"1.0.0"}"#,
237	        )
238	        .unwrap();
239	        let resolver = IdentityResolver::new(dir.path()).unwrap();
240	
241	        let a = resolver.resolve(std::path::Path::new("a"), Ecosystem::Cargo).unwrap();
242	        let b = resolver.resolve(std::path::Path::new("b"), Ecosystem::Npm).unwrap();
243	        assert_eq!(a.name(), "crate-a");
244	        assert_eq!(b.name(), "pkg-b");
245	    }
