256	    #[test]
257	    fn resolve_human_finds_prefixed_entry_for_unpromoted_package() {
258	        let mut index = IdentityIndex::default();
259	        let id = PackageId::Bare("foo".to_string());
260	        index.bare.insert("foo".to_string(), id.clone());
261	        index.native.insert((Ecosystem::Cargo, "foo".to_string()), id.clone());
262	        index.prefixed.insert((Ecosystem::Cargo, "foo".to_string()), id.clone());
263	        let resolved = index
264	            .resolve_human("cargo:foo", &[])
265	            .expect("cargo:foo must resolve via prefixed map");
266	        assert_eq!(resolved, id);
267	    }
