269	    #[test]
270	    fn resolve_human_unknown_ecosystem_prefix_falls_through_to_unknown() {
271	        let mut index = IdentityIndex::default();
272	        let id = PackageId::Bare("foo".to_string());
273	        index.bare.insert("foo".to_string(), id.clone());
274	        index.native.insert((Ecosystem::Cargo, "foo".to_string()), id.clone());
275	        index.prefixed.insert((Ecosystem::Cargo, "foo".to_string()), id);
276	        let err = index.resolve_human("npm:foo", &[]).unwrap_err();
277	        assert!(
278	            matches!(err, GraphError::UnknownPackage { .. }),
279	            "expected UnknownPackage, got {err:?}"
280	        );
281	    }
