283	    #[test]
284	    fn resolve_native_with_fallback_returns_none_on_single_cross_ecosystem_candidate() {
285	        let mut index = IdentityIndex::default();
286	        let cargo_serde = PackageId::Bare("serde".to_string());
287	        index
288	            .native
289	            .insert((Ecosystem::Cargo, "serde".to_string()), cargo_serde);
290	        let mut diagnostics = Vec::new();
291	        let result = index.resolve_native_with_fallback(Ecosystem::Npm, "serde", &mut diagnostics);
292	        assert!(
293	            result.is_none(),
294	            "a same-ecosystem miss must never silently fall back to a cross-ecosystem match"
295	        );
296	        assert_eq!(diagnostics.len(), 1);
297	        assert_eq!(diagnostics[0].code, callisto_model::DiagnosticCode::UnknownPackage);
298	        assert_eq!(diagnostics[0].severity, callisto_model::DiagnosticSeverity::Warning);
299	    }
