302	    fn resolve_native_with_fallback_returns_none_and_one_diagnostic_for_two_candidates() {
303	        let mut index = IdentityIndex::default();
304	        index.native.insert(
305	            (Ecosystem::Cargo, "ambiguous-lib".to_string()),
306	            PackageId::Bare("ambiguous-lib".to_string()),
307	        );
308	        index.native.insert(
