328	        let cargo_serde = PackageId::Bare("serde".to_string());
329	        index
330	            .native
331	            .insert((Ecosystem::Cargo, "serde".to_string()), cargo_serde.clone());
332	        let result = index.resolve_native(Ecosystem::Npm, "serde");
333	        assert_eq!(
