341	#[derive(Clone, Debug, Default)]
342	pub struct IdentityIndex {
343	    pub bare: BTreeMap<String, PackageId>,
344	    pub prefixed: BTreeMap<(Ecosystem, String), PackageId>,
345	    pub native: BTreeMap<(Ecosystem, String), PackageId>,
346	    /// Keyed by a platform npm manifest's own package name (e.g.
347	    /// `"@myorg/my-crate-linux-x64-gnu"`) -- distinct from `owner`'s name
348	    /// when the owning package's primary identity comes from a
349	    /// higher-priority ecosystem sharing the same directory (a Cargo+npm
350	    /// Case D project, §M.6.1 M7: platform manifests belong to the owning
351	    /// `Package`, they are never independently-registered `Package`s of
352	    /// their own). The `ManifestRole::Platform` is carried alongside so
353	    /// `GroupTable::resolve` doesn't need a second disk read to recover it.
354	    pub platform: BTreeMap<String, (PackageId, PathBuf, ManifestRole)>,
355	}
356	
357	impl IdentityIndex {
358	    pub fn resolve_human(&self, name: &str, siblings: &[PackageId]) -> Result<PackageId, GraphError> {
359	        if let Ok(PackageId::Prefixed { ecosystem, name: n }) = PackageId::parse(name) {
360	            if let Some(id) = self.prefixed.get(&(ecosystem, n)) {
361	                return Ok(id.clone());
362	            }
363	        }
364	
365	        if let Some(id) = self.bare.get(name) {
366	            return Ok(id.clone());
367	        }
368	
369	        let mut candidates = Vec::new();
370	        for ((_eco, n), id) in &self.prefixed {
371	            if n == name {
372	                candidates.push(id.clone());
373	            }
374	        }
375	
376	        if candidates.len() == 1 {
377	            return Ok(candidates[0].clone());
378	        }
379	
380	        if candidates.len() > 1 && !siblings.is_empty() {
381	            for sib in siblings {
382	                for cand in &candidates {
383	                    if cand.ecosystem() == sib.ecosystem() {
384	                        return Ok(cand.clone());
385	                    }
386	                }
387	            }
388	        }
389	
390	        if candidates.is_empty() {
391	            Err(GraphError::UnknownPackage {
392	                id: PackageId::parse(name).unwrap_or_else(|_| PackageId::Bare(name.to_string())),
393	            })
394	        } else {
395	            Err(GraphError::AmbiguousName {
396	                name: name.to_string(),
397	                candidates,
398	            })
399	        }
400	    }
401	
402	    /// Look up a package by its native (manifest-declared) name.
403	    ///
404	    /// First tries the exact `(eco, name)` key. If that misses -- a
405	    /// package in one ecosystem depending on a different ecosystem's
406	    /// package by bare name (e.g. an npm package listing a cargo crate)
407	    /// -- falls back to scanning all ecosystems for `name`.
408	    ///
409	    /// Fallback finds exactly one match: returns it. Finds more than one
410	    /// (two ecosystems both have `name`): returns `None` to prevent
411	    /// silent misresolution -- callers holding a `&mut Vec<Diagnostic>`
412	    /// should use [`Self::resolve_native_with_fallback`] instead, to get
413	    /// a diagnostic.
414	    pub fn resolve_native(&self, eco: Ecosystem, name: &str) -> Option<&PackageId> {
415	        // Fast path: exact ecosystem match.
416	        if let Some(id) = self.native.get(&(eco, name.to_string())) {
417	            return Some(id);
418	        }
419	
420	        // Cross-ecosystem fallback.
421	        let mut candidates: Vec<&PackageId> = self
422	            .native
423	            .iter()
424	            .filter(|((e, n), _)| *e != eco && n == name)
425	            .map(|(_, id)| id)
426	            .collect();
427	
428	        // Deduplicate by pointer identity (multiple entries for the same ID
429	        // across different ecosystems, e.g. a package that is both cargo and
430	        // npm, should not be treated as ambiguous).
431	        candidates.dedup_by(|a, b| a == b);
432	
433	        match candidates.len() {
434	            1 => Some(candidates[0]),
435	            // 0 = not found; >1 = true ambiguity → caller should diagnose.
436	            _ => None,
437	        }
438	    }
439	
440	    /// Like [`Self::resolve_native`] but pushes a [`callisto_model::Diagnostic`] when
441	    /// cross-ecosystem ambiguity is detected (two packages with the same bare
442	    /// name in different ecosystems).
443	    pub fn resolve_native_with_fallback<'a>(
444	        &'a self,
445	        eco: Ecosystem,
446	        name: &str,
447	        diagnostics: &mut Vec<callisto_model::Diagnostic>,
448	    ) -> Option<&'a PackageId> {
449	        // Fast path: exact ecosystem match.
450	        if let Some(id) = self.native.get(&(eco, name.to_string())) {
451	            return Some(id);
452	        }
453	
454	        // Cross-ecosystem fallback: collect unique IDs from other ecosystems.
455	        let mut candidates: Vec<(Ecosystem, &PackageId)> = self
456	            .native
457	            .iter()
458	            .filter(|((e, n), _)| *e != eco && n == name)
459	            .map(|((e, _), id)| (*e, id))
460	            .collect();
461	        candidates.dedup_by(|a, b| a.1 == b.1);
462	
463	        match candidates.len() {
464	            0 => None,
465	            _ => {
466	                let candidate_names: Vec<String> = candidates
467	                    .iter()
468	                    .map(|(e, id)| format!("{}:{}", e.prefix(), id.name()))
469	                    .collect();
470	                diagnostics.push(callisto_model::Diagnostic {
471	                    code: callisto_model::DiagnosticCode::UnknownPackage,
472	                    severity: callisto_model::DiagnosticSeverity::Warning,
473	                    message: format!(
474	                        "dependency name `{}` is ambiguous across ecosystems: {}; \
475	                         add an ecosystem prefix (e.g. `cargo:{}`) to disambiguate",
476	                        name,
477	                        candidate_names.join(", "),
478	                        name,
479	                    ),
480	                    package: None,
481	                    path: None,
482	                    escalated_by: None,
483	                    governed_by: None,
484	                });
485	                None
486	            }
487	        }
488	    }
489	
490	    pub fn native_name(&self, id: &PackageId, eco: Ecosystem) -> Option<&str> {
491	        for ((e, name), registered_id) in &self.native {
492	            if e == &eco && registered_id == id {
493	                return Some(name.as_str());
494	            }
495	        }
496	        None
497	    }
498	
499	    pub fn native_names(&self, id: &PackageId) -> impl Iterator<Item = (Ecosystem, &str)> {
500	        let mut results = Vec::new();
501	        for ((e, name), registered_id) in &self.native {
502	            if registered_id == id {
503	                results.push((*e, name.as_str()));
504	            }
505	        }
506	        results.into_iter()
507	    }
508	
509	    pub fn display_form(&self, id: &PackageId) -> String {
510	        id.display_name()
511	    }
512	
513	    pub fn platforms_of(&self, owner: &PackageId) -> impl Iterator<Item = (&str, &Path)> {
514	        let mut results = Vec::new();
515	        for (name, (plat_owner, path, _role)) in &self.platform {
516	            if plat_owner == owner {
517	                results.push((name.as_str(), path.as_path()));
518	            }
519	        }
520	        results.into_iter()
521	    }
522	}
