231	fn validate_summary(summary: &str) -> Result<String, CliError> {
232	    let trimmed = summary.trim().to_string();
233	    if trimmed.is_empty() {
234	        return Err(CliError::Other(
235	            "--summary cannot be empty. Provide a non-empty description of the change.".to_string(),
