241	/// Builds the list of package names shown in the interactive multiselect wizard.
242	///
243	/// Uses `.display_name()` so that packages sharing a bare name across different
244	/// ecosystems (e.g. `cargo/foo` and `npm/foo`) appear as distinct, qualified
245	/// entries in the list rather than two identical `"foo"` rows.
246	fn collect_package_names<'a>(packages: impl Iterator<Item = &'a callisto_model::Package>) -> Vec<String> {
247	    packages.map(|p| p.id.display_name()).collect()
248	}
