250	fn generate_human_slug() -> String {
251	    use std::sync::atomic::{AtomicU64, Ordering};
252	
253	    static COUNTER: AtomicU64 = AtomicU64::new(0);
254	
255	    let adjectives = [
256	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
257	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
258	    ];
259	    let nouns = [
260	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
261	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
262	    ];
263	    let verbs = [
264	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
265	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
266	    ];
267	
268	    // Each word list has 20 entries; total combination space is 20^3 = 8,000.
269	    // We map consecutive counter values to unique triples via integer division:
270	    //   a = idx % 20, n = (idx / 20) % 20, v = (idx / 400) % 20
271	    // This is a bijection on {0..7999}, so 8,000 consecutive calls all yield
272	    // distinct slugs regardless of OS clock resolution.
273	    //
274	    // A timestamp-derived offset rotates the starting position across process
275	    // restarts so repeated runs don't produce the same slug sequence.
276	    let ts = std::time::SystemTime::now()
277	        .duration_since(std::time::UNIX_EPOCH)
278	        .map(|d| d.as_nanos() as u64)
279	        .unwrap_or(0);
280	
281	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
282	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
283	    let offset = (ts >> 10) % 8000;
284	    let idx = (count + offset) % 8000;
285	
286	    let a = adjectives[(idx % 20) as usize];
287	    let n = nouns[((idx / 20) % 20) as usize];
288	    let v = verbs[((idx / 400) % 20) as usize];
289	
290	    format!("{a}-{n}-{v}")
291	}
