369	    /// Consecutive calls to generate_human_slug() must all produce distinct values,
370	    /// even when the OS clock resolution coalesces rapid calls to the same tick.
371	    #[test]
372	    fn test_generate_human_slug_consecutive_calls_differ() {
373	        let slugs: HashSet<String> = (0..50).map(|_| generate_human_slug()).collect();
374	        assert_eq!(
375	            slugs.len(),
376	            50,
377	            "expected 50 distinct slugs from 50 consecutive calls; got {} unique values",
378	            slugs.len()
379	        );
380	    }
