383	    /// interactive wizard's package-selection list must show two distinct,
384	    /// ecosystem-qualified names so the user can tell them apart.
385	    ///
386	    /// Fails before the fix (`.name()` produces two identical `"foo"` entries)
387	    /// and passes after the fix (`.display_name()` produces `"cargo/foo"` and
388	    /// `"npm/foo"`).
389	    #[test]
390	    fn polyglot_package_selection_names_are_distinct() {
391	        let packages = [make_package("cargo/foo"), make_package("npm/foo")];
392	        let names = collect_package_names(packages.iter());
393	
394	        assert_eq!(names.len(), 2, "expected 2 entries; got {names:?}");
395	        assert!(
396	            names.contains(&"cargo/foo".to_string()),
397	            "expected ecosystem-qualified name 'cargo/foo'; got {names:?}"
398	        );
399	        assert!(
400	            names.contains(&"npm/foo".to_string()),
401	            "expected ecosystem-qualified name 'npm/foo'; got {names:?}"
402	        );
403	    }
404	}
