192	    /// F16 regression: a second `resolve` call for the identical
193	    /// `(project_root, ecosystem)` pair must be served from the memo, not
194	    /// re-read from disk. Proven by deleting the manifest file between the
195	    /// two calls -- if the second call fell through to disk, it would error
196	    /// (file missing) instead of returning the memoized id.
197	    #[test]
198	    fn resolve_memoizes_and_does_not_re_read_deleted_manifest() {
199	        let dir = tempfile::tempdir().unwrap();
200	        let manifest_path = dir.path().join("Cargo.toml");
201	        std::fs::write(
202	            &manifest_path,
203	            "[package]\nname = \"memo-crate\"\nversion = \"0.1.0\"\n",
204	        )
205	        .unwrap();
206	        let resolver = IdentityResolver::new(dir.path()).unwrap();
207	
208	        let first = resolver.resolve(std::path::Path::new("."), Ecosystem::Cargo).unwrap();
209	        assert_eq!(first.name(), "memo-crate");
