1	use std::collections::BTreeMap;
2	use std::path::{Path, PathBuf};
3	use std::sync::Mutex;
4	
5	use callisto_model::{Ecosystem, ManifestRole, PackageId};
6	
7	use crate::error::GraphError;
8	
9	/// Test-observability counter: total number of times [`IdentityResolver::resolve`]
10	/// has actually read and parsed a manifest from disk (i.e. missed its memo).
11	/// Production code never reads this; it exists so callers can write
12	/// regression tests asserting that a given `(path, ecosystem)` pair is
13	/// resolved (read + parsed) at most once per [`IdentityResolver`] lifetime,
14	/// instead of once per caller. Mirrors `callisto_manifests::open_call_count`.
15	static IDENTITY_READ_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
16	
17	/// Resets the internal identity-read call counter to zero. Intended for use in test setup.
18	pub fn reset_identity_read_count() {
19	    IDENTITY_READ_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
20	}
21	
22	/// Reads the current value of the internal identity-read call counter.
23	pub fn identity_read_count() -> usize {
24	    IDENTITY_READ_COUNT.load(std::sync::atomic::Ordering::SeqCst)
25	}
26	
27	pub struct IdentityResolver {
28	    workspace_root: PathBuf,
29	    /// Memoizes `resolve`'s result per `(project_root, ecosystem)` so a
30	    /// manifest referenced by many dependency edges (e.g. a widely-depended-on
31	    /// shared crate) is read and parsed from disk at most once per resolver
32	    /// lifetime, rather than once per caller. `MoonProjectLocator` holds a
33	    /// single `IdentityResolver` for its whole lifetime, so this memo spans
34	    /// both `projects()` and `declared_edges()` -- the two call sites that
35	    /// previously re-resolved the same identity independently.
36	    memo: Mutex<BTreeMap<(PathBuf, Ecosystem), PackageId>>,
37	}
38	
39	impl IdentityResolver {
40	    pub fn new(workspace_root: &Path) -> Result<Self, GraphError> {
41	        Ok(IdentityResolver {
42	            workspace_root: workspace_root.to_path_buf(),
43	            memo: Mutex::new(BTreeMap::new()),
44	        })
45	    }
46	
47	    pub fn resolve(&self, project_root: &Path, ecosystem: Ecosystem) -> Result<PackageId, GraphError> {
48	        let key = (project_root.to_path_buf(), ecosystem);
49	        if let Some(id) = self.memo.lock().unwrap_or_else(|e| e.into_inner()).get(&key) {
50	            return Ok(id.clone());
51	        }
52	
53	        let abs = self.workspace_root.join(project_root);
54	        let Some(format) = ecosystem.canonical_manifest_format() else {
55	            return Err(GraphError::UnsupportedIdentityEcosystem { ecosystem });
56	        };
57	
58	        let manifest_rel = project_root.join(format.file_name());
59	        let manifest_abs = abs.join(format.file_name());
60	        IDENTITY_READ_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
61	        let content = std::fs::read_to_string(&manifest_abs).map_err(|e| callisto_model::ManifestError::Read {
62	            path: manifest_rel.clone(),
63	            message: e.to_string(),
64	        })?;
65	        let identity = callisto_manifests::read_identity(format, &content, &manifest_rel)?;
66	        let name = identity.name.ok_or(callisto_model::ManifestError::MissingField {
67	            path: manifest_rel.clone(),
68	            field: match ecosystem {
69	                Ecosystem::Cargo => "package.name",
70	                Ecosystem::Npm => "name",
71	                _ => "project.name / tool.poetry.name / tool.flit.metadata.module",
72	            },
73	        })?;
74	
75	        let id = PackageId::parse(&name).map_err(|err| GraphError::PackageIdentifierParse {
76	            path: manifest_rel,
77	            name: name.clone(),
78	            source: err,
79	        })?;
80	
81	        self.memo
82	            .lock()
83	            .unwrap_or_else(|e| e.into_inner())
84	            .insert(key, id.clone());
85	        Ok(id)
86	    }
87	}
