169	fn cross_ecosystem_npm_to_cargo_dep_edge_is_discovered() {
170	    let tmp = tempfile::tempdir().unwrap();
171	    let root = tmp.path();
172	    git_init(root);
173	
174	    // Workspace Cargo.toml
175	    fs::write(
176	        root.join("Cargo.toml"),
177	        "[workspace]\nmembers = [\"crates/*\"]\nresolver = \"2\"\n",
178	    )
179	    .unwrap();
180	
181	    // Cargo crate
182	    let crate_dir = root.join("crates/rust-addon");
183	    fs::create_dir_all(&crate_dir).unwrap();
184	    fs::write(
185	        crate_dir.join("Cargo.toml"),
186	        "[package]\nname = \"rust-addon\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
187	    )
188	    .unwrap();
189	
190	    // npm package depending on the cargo crate by bare name
191	    let npm_dir = root.join("packages/my-app");
192	    fs::create_dir_all(&npm_dir).unwrap();
193	    fs::write(
194	        npm_dir.join("package.json"),
195	        r#"{"name":"my-app","version":"1.0.0","dependencies":{"rust-addon":"^1.0.0"}}"#,
196	    )
197	    .unwrap();
198	
199	    let locator = IgnoreWalkLocator::new(root);
200	    let runner = NoopRunner;
201	
202	    let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace should load");
203	
204	    let cargo_id = PackageId::parse("rust-addon").unwrap();
205	    let npm_id = PackageId::parse("my-app").unwrap();
206	
207	    // Both packages must be discovered
208	    let pkg_names: Vec<_> = ws.graph.packages().map(|p| p.id.name().to_string()).collect();
209	    assert!(
210	        pkg_names.contains(&"rust-addon".to_string()),
211	        "cargo crate should be discovered; got: {:?}",
212	        pkg_names
213	    );
214	    assert!(
215	        pkg_names.contains(&"my-app".to_string()),
216	        "npm package should be discovered; got: {:?}",
217	        pkg_names
218	    );
219	
220	    // No cross-ecosystem DepEdge is created (AC-12/AC-14): same-ecosystem-first
221	    // resolution treats the cargo-only name as unresolved from npm.
222	    let edges: Vec<_> = ws.graph.dependencies_of(&npm_id).collect();
223	    assert!(
224	        !edges.iter().any(|e| e.to == cargo_id),
225	        "cross-ecosystem edge my-app -> rust-addon must NOT exist (AC-12/AC-14); \
