230	    // An UnknownPackage Warning diagnostic naming cargo:rust-addon must be present instead.
231	    assert!(
232	        ws.graph.diagnostics().iter().any(|d| {
233	            d.code == callisto_model::DiagnosticCode::UnknownPackage
234	                && d.severity == callisto_model::DiagnosticSeverity::Warning
235	                && d.message.contains("cargo:rust-addon")
236	        }),
