241	/// Unit test for `IdentityIndex::resolve_native` cross-ecosystem fallback.
242	/// Looking up a cargo crate by its bare name under the Npm ecosystem key
243	/// should return the crate when there is no ambiguity.
244	#[test]
245	fn resolve_native_falls_back_across_ecosystem_boundary() {
246	    use callisto_graph::IdentityIndex;
247	    use callisto_model::Ecosystem;
248	
249	    let cargo_id = PackageId::parse("rust-addon").unwrap();
250	
251	    let mut index = IdentityIndex::default();
252	    index
253	        .native
254	        .insert((Ecosystem::Cargo, "rust-addon".to_string()), cargo_id.clone());
255	
256	    // Same-ecosystem lookup still works
257	    assert_eq!(
258	        index.resolve_native(Ecosystem::Cargo, "rust-addon"),
259	        Some(&cargo_id),
260	        "same-ecosystem lookup should still work"
261	    );
262	
263	    // Cross-ecosystem fallback: Npm lookup should find the Cargo crate
264	    assert_eq!(
265	        index.resolve_native(Ecosystem::Npm, "rust-addon"),
266	        Some(&cargo_id),
267	        "cross-ecosystem fallback should return the cargo crate when no npm entry exists"
268	    );
269	}
270	
271	/// When the same bare name is indexed under two different ecosystems, and both
272	/// entries resolve to the same `PackageId` value, the cross-ecosystem fallback
273	/// correctly deduplicates and returns that single shared ID.
274	///
275	/// Note: in a valid workspace, two packages at *different* paths with the same
276	/// bare name would both produce `PackageId::Bare("name")` (identical values).
277	/// The walk builder already conflates them into a single `Package` entry, so
278	/// at the `resolve_native` level the two ecosystem registrations are not
279	/// truly ambiguous — they both point to the same logical package.
280	#[test]
281	fn resolve_native_deduplicates_same_bare_name_across_ecosystems() {
282	    use callisto_graph::IdentityIndex;
283	    use callisto_model::Ecosystem;
284	
285	    // Both produce PackageId::Bare("shared-name") — equal values.
286	    let shared_id = PackageId::parse("shared-name").unwrap();
287	
288	    let mut index = IdentityIndex::default();
289	    index
290	        .native
291	        .insert((Ecosystem::Cargo, "shared-name".to_string()), shared_id.clone());
292	    index
293	        .native
294	        .insert((Ecosystem::Pypi, "shared-name".to_string()), shared_id.clone());
295	
296	    // Npm lookup: both Cargo and Pypi entries resolve to the same PackageId,
297	    // so dedup collapses them and returns that single ID.
298	    let result = index.resolve_native(Ecosystem::Npm, "shared-name");
299	    assert_eq!(
300	        result,
301	        Some(&shared_id),
302	        "two ecosystem entries with equal PackageIds should deduplicate to one result"
303	    );
304	}
